# 3. Công thức cộng
$$
\sin (\boldsymbol {a} \pm \boldsymbol {b}) = \sin \boldsymbol {a}. \cos \boldsymbol {b} \pm \cos \boldsymbol {a}. \sin \boldsymbol {b}
$$

$$
\cos (\boldsymbol {a} \pm \boldsymbol {b}) = \cos \boldsymbol {a}. \cos \boldsymbol {b} \mp \sin \boldsymbol {a}. \sin \boldsymbol {b}
$$

$$
\tan (\boldsymbol {a} \pm \boldsymbol {b}) = \frac {\tan \boldsymbol {a} \pm \tan \boldsymbol {b}}{1 \mp \tan \boldsymbol {a} . \tan \boldsymbol {b}}
$$

# 4.1 Công thức nhân đôi
$$
\sin 2 \boldsymbol {a} = 2 \sin \boldsymbol {a} \cos \boldsymbol {a}
$$

$$
\cos 2 \boldsymbol {a} = \cos^ {2} \boldsymbol {a} - \sin^ {2} \boldsymbol {a} = 2 \cos^ {2} \boldsymbol {a} - 1 = 1 - 2 \sin^ {2} \boldsymbol {a}
$$

$$
\tan 2 \boldsymbol {a} = \frac {2 \text {tana}}{1 - \tan^ {2} \boldsymbol {a}}
$$

# 4.2 Công thức nhân ba
$$
\sin 3 \boldsymbol {a} = 3 \sin \boldsymbol {a} - 4 \sin^ {3} \boldsymbol {a}
$$

$$
\cos 3 \boldsymbol {a} = 4 \cos^ {3} \boldsymbol {a} - 3 \cos \boldsymbol {a}
$$

$$
\tan 3 \boldsymbol {a} = \frac {3 \tan \boldsymbol {a} - \tan^ {3} \boldsymbol {a}}{1 - 3 \tan^ {2} \boldsymbol {a}}
$$

# 5. Công thức hạ bậc
$$
\sin^ {2} \boldsymbol {a} = \frac {1 - \cos 2 \boldsymbol {a}}{2}
$$

$$
\cos^ {2} \boldsymbol {a} = \frac {1 + \cos 2 \boldsymbol {a}}{2}
$$

$$
\sin^ {3} \boldsymbol {a} = \frac {3 \sin \boldsymbol {a} - \sin 3 \boldsymbol {a}}{4}
$$

$$
\cos^ {3} \boldsymbol {a} = \frac {3 \cos \boldsymbol {a} + \cos 3 \boldsymbol {a}}{4}
$$
